    "clinicalCase": "Paciente, 4 anos, é levado à Unidade Básica de Saúde pelos pais com queixa de manter perda de urina durante a noite 1 a 2 vezes por semana, principalmente quando dorme profundamente, apesar de ter desenvolvido o controle esfincteriano diurno desde 3 anos e meio de idade. Não há histórico de infecção urinária, dor ao urinar, aumento da frequência urinária ou urgência miccional. Apresenta sono profundo, com dificuldade para despertar. Desenvolvimento neuropsicomotor adequado para a idade. Exame físico sem alterações.\n\nExames laboratoriais:\n- EAS (urina tipo I): Sem alterações\n- Urocultura: Negativa (Ausência de crescimento)\n- Glicemia de jejum: 86 mg/dL (Valor de referência: 70 a 105 mg/dL)\n- Ultrassonografia de rins e vias urinárias: Normal\n\nQual é a principal hipótese diagnóstica?",
    "options": [
      {
        "id": "A",
        "text": "Controle esfincteriano em desenvolvimento.",
        "isCorrect": true,
        "explanation": "Correto. De acordo com as diretrizes pediátricas e urológicas (ICCS / SBP), o controle esfincteriano noturno é um marco do desenvolvimento que se consolida progressivamente até os 5 anos de idade. Perdas urinárias involuntárias durante o sono em crianças menores de 5 anos (especialmente com frequência baixa de 1 a 2 vezes por semana em sono profundo e sem sintomas diurnos ou alterações em exames) são consideradas fisiológicas, refletindo imaturidade do controle esfincteriano em desenvolvimento."
      },
      {
        "id": "B",
        "text": "Micção disfuncional neurogênica.",
        "isCorrect": false,
        "explanation": "Incorreto. A bexiga neurogênica ou micção disfuncional neurológica cursa com disfunção miccional diurna, retenção urinária, infecções urinárias de repetição, alterações ao exame neurológico e alterações no trato urinário ao ultrassom, ausentes no paciente."
      },
      {
        "id": "C",
        "text": "Enurese noturna secundária.",
        "isCorrect": false,
        "explanation": "Incorreto. O diagnóstico formal de enurese só é estabelecido a partir dos 5 anos de idade (DSM-5 e ICCS). Além disso, a forma secundária exigiria um período prévio de continência noturna de pelo menos 6 meses, o que a criança nunca apresentou."
      },
      {
        "id": "D",
        "text": "Bexiga hiperativa.",
        "isCorrect": false,
        "explanation": "Incorreto. A síndrome da bexiga hiperativa caracteriza-se por urgência miccional diurna, aumento da frequência urinária (> 8 vezes/dia) e urge-incontinência diurna, sintomas explicitamente negados na anamnese."
      }
    ],
