    "clinicalCase": "Mulher de 58 anos em acompanhamento na Unidade Básica de Saúde, apresentou valores pressóricos de 150 x 92 mmHg na primeira consulta e 154 x 96 mmHg na segunda, duas semanas depois, ambos aferidos com técnica adequada. A paciente relata dieta inadequada e sedentarismo. Não há lesões de órgão-alvo e o risco cardiovascular é baixo.\n\nConsiderando o Protocolo Clínico e Diretrizes Terapêuticas da Hipertensão Arterial Sistêmica do Ministério da Saúde (2025), qual(is) ação(ões) deve(m) integrar o plano terapêutico individual dessa paciente?",
