    "clinicalCase": "Primigesta de 28 anos com idade gestacional de 41 semanas foi admitida para assistência ao trabalho de parto espontâneo. Negou comorbidades e não apresentou intercorrências durante o pré-natal. Oito horas após a admissão, evoluiu para período expulsivo, em posição de litotomia. Porém, após a exteriorização da cabeça, esta retraiu-se contra o períneo e não houve o desprendimento fetal. Diante deste quadro, qual deve ser a conduta inicial do médico?",
    "options": [
      {
        "id": "A",
        "text": "Reposicionar a paciente promovendo hiperflexão das pernas e das coxas.",
        "isCorrect": true,
        "explanation": "Correto. O quadro clínico descreve uma distócia de ombro (com o clássico 'sinal da tartaruga' - retração da cabeça fetal contra o períneo). A conduta inicial de primeira linha recomendada pelas diretrizes obstétricas (ACOG, RCOG, FEBRASGO) é a Manobra de McRoberts, que consiste no reposicionamento da paciente promovendo a hiperflexão e abdução das coxas maternas sobre o abdome, associada ou não à pressão suprapúbica (manobra de Rubin I)."
      },
      {
        "id": "B",
        "text": "Realizar tração forte e contínua no polo cefálico e pressão no fundo uterino.",
        "isCorrect": false,
        "explanation": "Incorreto. A tração excessiva do polo cefálico e a pressão no fundo uterino (manobra de Kristeller) são formalmente contraindicadas na distócia de ombro pelo altíssimo risco de lesão de plexo braquial, fratura de clavícula/úmero e rotura uterina."
      },
      {
        "id": "C",
        "text": "Introduzir a mão pelo vazio sacral e promover a adução do ombro anterior .",
        "isCorrect": false,
        "explanation": "Incorreto. As manobras internas (como manobra de Woods, Rubin II ou desprendimento do braço posterior) são manobras secundárias que só devem ser tentadas caso as manobras iniciais de primeira linha (McRoberts e pressão suprapúbica) falhem."
      },
      {
        "id": "D",
        "text": "Realizar episiotomia medio-lateral ampla.",
        "isCorrect": false,
        "explanation": "Incorreto. A episiotomia não previne nem resolve a distócia de ombro óssea por si só, sendo indicada apenas se houver necessidade de espaço para manobras internas intrauterinas subsequentes."
      }
    ],
