    "clinicalCase": "Homem de 57 anos faz uso de amitriptilina 100 mg/dia, há mais de 10 anos, para melhora do sono e diminuição da sensação de ansiedade. Sem histórico de comorbidades ou uso de outra medicação. Busca consulta médica em Unidade Básica de Saúde para avaliar riscos do uso prolongado da medicação.\n\nQuais exames complementares são indicados para o acompanhamento do uso de amitriptilina nesse paciente?",
    "options": [
      {
        "id": "A",
        "text": "Creatinina, transminases hepáticas, potássio sérico e eletrocardiograma.",
        "isCorrect": true,
        "explanation": "Correto. A amitriptilina é um antidepressivo tricíclico com potente ação anticolinérgica, alfa-bloqueadora e bloqueadora dos canais de sódio e potássio cardíacos. O uso prolongado e em doses moderadas/altas (100 mg/dia) pode induzir cardiotoxicidade (alargamento de QRS, prolongamento de QTc e arritmias, agravadas por distúrbios do potássio sérico). Além disso, possui metabolização predominantemente hepática e excreção renal. Portanto, o acompanhamento seguro inclui avaliação da função renal (creatinina), enzimas hepáticas (transaminases), eletrólitos (potássio) e Eletrocardiograma (ECG)."
      },
      {
        "id": "B",
        "text": "Creatinina, lipidograma e TSH séricos e ultrassonografia de abdome.",
        "isCorrect": false,
        "explanation": "Incorreto. Ultrassonografia de abdome e TSH não são exames indicados para monitorização específica de toxicidade por tricíclicos; além disso, a ausência de ECG compromete a avaliação do risco cardíaco arritmogênico."
      },
      {
        "id": "C",
        "text": "Transminases hepáticas, potássio sérico, ultrassonografia de abdome e radiografia de tórax.",
        "isCorrect": false,
        "explanation": "Incorreto. Ultrassonografia abdominal e radiografia de tórax não fazem parte do protocolo de seguimento de toxicidade por amitriptilina."
      },
      {
        "id": "D",
        "text": "Sódio, potássio, lipidograma e TSH séricos, eletrocardiograma e radiografia de tórax.",
        "isCorrect": false,
        "explanation": "Incorreto. A radiografia de tórax e o lipidograma não são exames de rotina para monitorização de amitriptilina, faltando a dosagem de creatinina e transaminases hepáticas."
      }
    ],
