    "clinicalCase": "Uma criança de 6 anos, do sexo feminino, é levada ao Ambulatório de Pediatria pela mãe devido à queixa de reclamações na escola por falta de atenção e sonolência excessiva. Segundo a mãe, a criança apresenta respiração oral ruidosa que piora durante o sono, com roncos e episódios de apneia, acordando várias vezes durante a noite com a boca seca e pedindo água. A mãe nega febre, tosse ou secreção nasal, que ocorrem apenas quando a criança fica gripada, o que é frequente. Nega prurido nasal ou espirros, assim como antecedentes familiares patológicos. Ao exame, a criança apresenta fácies congestas, com vedamento labial incompleto, respiração bucal ruidosa e olheiras. Otoscopia normal bilateralmente. Mucosas e cornetos nasais com leve hiperemia; cavidade oral com palato em ogiva; tonsilas palatinas com leve aumento e ausência de placas ou secreções. Ausculta pulmonar com roncos de transmissão.\n\nQual o exame complementar confirmatório a ser solicitado?",
