    "clinicalCase": "Homem, 28 anos, é admitido na sala de trauma de uma Unidade de Emergência vítima de colisão automobilística em alta velocidade com desaceleração súbita. Encontra-se consciente, queixa-se de dor torácica difusa. Ao exame, PA 110 x 70 mmHg, FC 110 bpm e oximetria de pulso de 96% (em ar ambiente); sem jugulares túrgidas ou assimetrias na expansibilidade torácica, percussão torácica timpânica bilateral e bulhas normofonéticas. Apresenta escoriações na parede anterior do tórax. A radiografia de tórax inicial revela mediastino alargado, apagamento do botão aórtico e desvio da traqueia para a direita.\nA principal hipótese diagnóstica é",
