        "isCorrect": true,
        "explanation": "Correta. A rotura ou transecção traumática da aorta torácica é uma lesão potencialmente fatal frequentemente associada a mecanismos de desaceleração rápida (como colisões frontais ou quedas de grande altura). Os achados radiológicos clássicos no raio X de tórax incluem alargamento do mediastino superior (> 8 cm no adulto), apagamento ou perda do contorno do botão aórtico, desvio da traqueia e da sonda nasogástrica para a direita e rebaixamento do brônquio-fonte esquerdo."
