    "clinicalCase": "Puérpera, 24 anos, imigrante recém-chegada ao Brasil, é admitida na maternidade 30 minutos após parto extra-hospitalar. Relata que o parto ocorreu rapidamente, sendo a placenta completamente expulsa alguns minutos após. Ao exame inicial, apresenta-se hemodinamicamente estável e com útero contraído, apesar de manter sangramento vaginal moderado. Ao exame do canal de parto, identifica-se laceração perineal envolvendo pele, mucosa vaginal e musculatura perineal, sem acometimento do esfíncter anal ou da mucosa retal. A paciente demonstra ansiedade, dificuldade de compreensão do idioma e questiona repetidamente o que será feito.\nConsiderando a avaliação realizada e as boas práticas recomendadas pela OMS e pelo Ministério da Saúde para uma assistência humanizada, a conduta adequada é",
