    "clinicalCase": "Em um território coberto por uma equipe de Saúde da Família, há uma fábrica de cimento perto das moradias. A equipe identifica aumento de atendimentos por sintomas respiratórios em trabalhadores e outros moradores locais, além de relatos de poeira de cimento dentro das casas. Diante dessa situação, o médico, junto à equipe, propõe elaborar um projeto de intervenção com foco em ações de prevenção aos agravos identificados.\nNesse contexto, qual é a proposta de intervenção adequada?",
