        "explanation": "Correta. No âmbito da Atenção Primária e da Saúde Coletiva, ao identificar riscos e agravos decorrentes de poluição ambiental e atividade industrial que impactam a população adscrita, a equipe de Saúde da Família deve articular-se e acionar os órgãos competentes de Vigilância em Saúde (Vigilância Ambiental em Saúde - VIGIAR, Vigilância Sanitária e Vigilância em Saúde do Trabalhador - CEREST) para inspeção, fiscalização e pactuação de medidas intersetoriais de mitigação."
