    "itemCode": "169287",
    "clinicalCase": "Uma equipe de Saúde da Família está investigando o aumento de consultas por dores lombares entre trabalhadores de um polo têxtil localizado em seu território. A gestão municipal solicita que a equipe identifique se há associação entre o tipo de atividade laboral e a ocorrência de dor lombar ao longo dos anos, para subsidiar ações intersetoriais de prevenção com a Secretaria de Trabalho e Assistência Social.\nNesse cenário, o tipo de estudo epidemiológico mais adequado para identificar a associação entre exposição ocupacional e dor lombar é",
    "options": [
      {
        "id": "A",
        "text": "estudo ecológico.",
        "isCorrect": false,
        "explanation": "Incorreta. O estudo ecológico tem como unidade de observação grupos populacionais (agregados) e não indivíduos, não permitindo vincular diretamente a exposição individual ao desenvolvimento do desfecho (sujeito à falácia ecológica)."
      },
      {
        "id": "B",
        "text": "estudo transversal.",
        "isCorrect": false,
        "explanation": "Incorreta. O estudo transversal avalia a exposição e o desfecho simultaneamente em um único ponto no tempo, medindo prevalência, sem capacidade de assegurar causalidade temporal ou incidência acumulada ao longo dos anos."
      },
      {
        "id": "C",
        "text": "estudo de coorte.",
        "isCorrect": true,
        "explanation": "Correta. O estudo de coorte é um desenho observacional longitudinal no qual indivíduos livres do agravo são classificados conforme o status de exposição (diferentes atividades laborais no polo têxtil) e acompanhados ao longo do tempo para determinar a incidência do desfecho (dor lombar). É o modelo ideal para estabelecer a sequência temporal entre exposição e desfecho e estimar o risco relativo."
      },
      {
        "id": "D",
        "text": "ensaio clínico.",
        "isCorrect": false,
        "explanation": "Incorreta. O ensaio clínico é um estudo intervencionista/experimental em que o pesquisador introduz intencionalmente uma exposição ou intervenção terapêutica, sendo eticamente inviável e inapropriado para investigar exposições a riscos ocupacionais."
      }
    ],
    "correctAnswer": "C",
