    "clinicalCase": "Homem, 35 anos, dá entrada na Unidade de Pronto Atendimento (UPA), trazido pelo suporte básico do SAMU em prancha rígida e colar cervical, após queda de moto há 40 minutos. Encontra-se confuso, referindo dor em pelve e hipogástrio. Avaliação primária: Vias aéreas pérvias; respiração espontânea, sem esforço, FR 24 irpm e murmúrio vesicular simétrico. PA 96 x 58 mmHg; FC  124 bpm; pele fria, sudorese profusa e tempo de enchimento capilar lentificado. Abdome doloroso em hipogástrio, com ruídos hidroaéreos diminuídos; pelve instável. Glasgow 13 (O3 V4 M6), pupilas isocóricas e fotorreagentes. A UPA dispõe apenas de hemograma e radiografia simples; não possui tomografia computadorizada, banco de sangue ou cirurgião. O hospital de referência em trauma situa-se a 34 km.\nConsiderando os princípios do atendimento inicial ao trauma e a capacidade resolutiva da unidade, qual é a conduta prioritária mais adequada?",
