    "clinicalCase": "Menina, 5 anos, é levada à Unidade de Pronto Atendimento após mordedura na mão direita pelo cachorro da vizinha. O animal encontra-se saudável, vacinado e é passível de observação.\n\nAlém dos cuidados com o ferimento e a observação do cão por 10 dias, quais são as recomendações do Ministério da Saúde para profilaxia antirrábica humana e as normas de vigilância epidemiológica?",
