        "text": "Observar a criança, não administrar vacina ou soro antirrábico e notificar em até 24h da exposição.",
        "isCorrect": true,
        "explanation": "Correto. Conforme o Guia de Vigilância em Saúde e a Norma Técnica de Profilaxia da Raiva Humana do Ministério da Saúde, em acidentes causados por cão ou gato domiciliado, clinicamente sadio e passível de observação por 10 dias, a conduta consiste em lavagem rigorosa do ferimento e observação do animal por 10 dias, sem indicação imediata de vacina ou soro antirrábico (que só serão iniciados se o animal adoecer, morrer ou desaparecer). Além disso, o atendimento antirrábico é agravo de notificação compulsória."
