        "isCorrect": true,
        "explanation": "Correto. De acordo com o protocolo ATLS (Advanced Trauma Life Support), a gestante a partir de 20 semanas em decúbito dorsal horizontal apresenta compressão mecânica da veia cava inferior pelo útero gravídico, o que reduz drasticamente o retorno venoso e o débito cardíaco (síndrome da hipotensão supina). A lateralização da prancha rígida em 15° a 30° para a esquerda (ou deslocamento manual do útero para a esquerda) alivia a compressão da cava, melhora imediatamente o débito cardíaco e é passo fundamental e prioritário no manejo da hipotensão no trauma gestacional."
