    "clinicalCase": "Uma menina de 7 anos é levada a ambulatório especializado pela mãe, que relata o aparecimento de pelos pubianos e aumento da região mamária há cerca de dois meses. Não há relato de uso de medicamentos, doenças crônicas ou exposição a substâncias hormonais. A criança apresenta estatura correspondente a escore Z igual a zero para a idade, sem desvio prévio documentado. Ao exame físico, observa-se tecido mamário palpável sob a aréola, sem separação do contorno mamário, compatível com Tanner M2, além de pelos pubianos escuros, grossos e levemente encaracolados, restritos à região labial, correspondendo a Tanner P2.\n\nQual alteração no mecanismo fisiológico explica os achados descritos no caso?",
    "options": [
      {
        "id": "A",
        "text": "Secreção aumentada de andrógenos pela suprarrenal.",
        "isCorrect": false,
        "explanation": "Incorreto. A secreção isolada de andrógenos suprarrenais (adrenarca precoce ou hiperplasia adrenal congênita) causaria apenas pubarca/adrenarca e possíveis sinais de virilização, sem desencadear o desenvolvimento do broto mamário (telarca / M2), que é estrogênio-dependente."
      },
      {
        "id": "B",
        "text": "Conversão periférica de andrógenos em estrogênios.",
        "isCorrect": false,
        "explanation": "Incorreto. A conversão periférica por aromatase ocorre predominantemente no tecido adiposo em quadros de obesidade grave ou tumores produtores de andrógenos, não constituindo a causa primária do desenvolvimento puberal completo e harmonioso."
      },
      {
        "id": "C",
        "text": "Ativação do eixo hipotálamo-hipófise-gonadal.",
        "isCorrect": true,
        "explanation": "Correto. O surgimento de telarca (M2) associada a pubarca (P2) antes dos 8 anos de idade em meninas caracteriza a Puberdade Precoce Central (PPC, verdadeira ou GnRH-dependente). O mecanismo fisiopatológico primário é a ativação prematura e pulsátil do eixo hipotálamo-hipófise-gonadal, resultando na liberação de GnRH hipotalâmico, secreção das gonadotrofinas hipofisárias (LH e FSH) e subsequente estimulação ovariana com produção de esteroides sexuais (estrogênios e androgênios)."
      },
      {
        "id": "D",
        "text": "Hipersensibilidade a níveis basais de esteroides sexuais.",
        "isCorrect": false,
        "explanation": "Incorreto. A hipersensibilidade periférica a níveis basais de esteroides sexuais pode ocorrer em variantes benignas e isoladas do desenvolvimento puberal (como telarca precoce isolada ou adrenarca precoce isolada), mas não explica a evolução sincrônica e concomitante de telarca e pubarca (M2P2)."
      }
    ],
