        "id": "B",
        "text": "cristaloide, com monitorização do débito urinário nas primeiras horas.",
        "isCorrect": true,
        "explanation": "Correta. De acordo com o ATLS (10ª e 11ª edições) e a American Burn Association (ABA), a reposição volêmica no grande queimado adulto (≥ 20% de SCQ de 2º/3º grau) deve ser realizada com solução cristaloide isotônica (Ringer Lactato, calculada pela fórmula do ATLS: 2 mL x peso corporal em kg x % SCQ nas primeiras 24 horas, sendo 50% nas primeiras 8h a contar do momento do trauma). A titulação e o ajuste contínuo da infusão volêmica devem ser rigorosamente guiados pelo débito urinário (meta de 0,5 mL/kg/hora em adultos, ou 30 a 50 mL/h)."
