    "clinicalCase": "Mulher, 22 anos, é atendida no serviço de emergência hospitalar, encaminhada pela Unidade de Pronto Atendimento, com história de dor pélvica intensa há 5 dias, febre alta persistente, náuseas e vômitos. Relata corrimento vaginal purulento e piora progressiva do quadro, apesar de ter iniciado antibiótico oral há 48 horas. Ao exame físico, apresenta-se toxemiada, com dor abdominal difusa, defesa à palpação e dor intensa à mobilização do colo uterino. Ultrassonografia pélvica evidencia massa anexial complexa sugestiva de abscesso tubo-ovariano, medindo 3 cm de diâmetro.\nQual é a conduta adequada nesse cenário?",
