        "text": "Teleconsultoria entre profissionais, utilizada como apoio à decisão clínica, mantendo-se a responsabilidade assistencial com a médica da APS.",
        "isCorrect": true,
        "explanation": "Correta. De acordo com as normas de telessaúde do Ministério da Saúde e a Resolução CFM nº 2.314/2022, a teleconsultoria é a consulta registrada realizada exclusivamente entre profissionais de saúde (ou entre médicos), por meio de telecomunicação bidirecional síncrona ou assíncrona, com a finalidade de esclarecer dúvidas clínicas e apoiar a decisão terapêutica/diagnóstica. Na teleconsultoria, a responsabilidade direta pelo cuidado e pela condução do paciente permanece com o profissional solicitante da Atenção Primária."
