    "itemCode": "ITEM 163593 - V. 943501",
    "clinicalCase": "Homem, 64 anos, professor universitário aposentado, com histórico de hipertensão arterial sistêmica malcontrolada há anos e ex-tabagista, é levado por sua filha à Unidade Básica de Saúde, devido a queixas de declínio cognitivo, com início há cerca de 2 anos. Segundo o relato, o quadro teve início súbito durante episódio de pico hipertensivo, quando o paciente começou a apresentar dificuldades para planejar e executar atividades habituais, como organizar contas e seguir o uso correto de suas medicações (losartana e anlodipino). Desde então, ocorreu piora cognitiva em degraus, com períodos de estabilidade intercalados com novas perdas de desempenho. A filha destaca também episódios de instabilidade postural e quedas frequentes no mesmo período. O paciente apresenta déficit de memória recente, com razoável preservação de linguagem e orientação temporal. Não há histórico familiar de demência. Ao exame físico, PA 170 x 95 mmHg, reflexos patelares exaltados bilateralmente, além de marcha com base alargada e insegura. O miniexame do estado mental é de 22/30, com destaque para prejuízo em funções executivas e atenção.\n\nA principal hipótese diagnóstica para esse caso é de demência",
    "options": [
      {
        "id": "A",
        "text": "vascular.",
        "isCorrect": true,
        "explanation": "A demência vascular é caracterizada pelo início abrupto relacionado a eventos vasculares (como picos hipertensivos/isquemias), progressão em degraus (stepwise) com períodos de estabilização intercalados com novas perdas, predomínio inicial de disfunção executiva e atencional, e presença de sinais neurológicos focais/piramidais (hiper-reflexia patelar bilateral, distúrbios da marcha e instabilidade postural) em paciente com múltiplos fatores de risco cardiovascular (HAS de longa data, tabagismo)."
      },
      {
        "id": "B",
        "text": "frontotemporal.",
        "isCorrect": false,
        "explanation": "A demência frontotemporal (DFT) cursa tipicamente com alterações precoces e marcantes da personalidade e comportamento (desinibição, apatia, perda de empatia, hiperoralidade) ou afasia progressiva primária, com evolução insidiosa e contínua, sem a clássica progressão em degraus ligada a eventos vasculares."
      },
      {
        "id": "C",
        "text": "de corpúsculos de Lewy.",
        "isCorrect": false,
        "explanation": "A demência por corpos de Lewy tem como manifestações centrais o declínio cognitivo flutuante com variações acentuadas na atenção/vigília, alucinações visuais precoces e bem formadas, e sinais motores espontâneos de parkinsonismo."
      },
      {
        "id": "D",
        "text": "na doença de Alzheimer.",
        "isCorrect": false,
        "explanation": "A doença de Alzheimer tem início insidioso e progressão gradual/contínua (não em degraus), acometendo predominantemente a memória episódica recente desde as fases iniciais, sem relação temporal direta com picos pressóricos ou sinais motores/focais precoces."
      }
    ],
