    "clinicalCase": "Um menino de 5 anos, previamente saudável, é trazido à emergência com dor nos membros inferiores iniciada há 4 dias, dificuldade para correr e andar, e surgimento de petéquias no tronco inferior e pernas há 24 horas. Apresentou febre (38 °C) no 1º dia do quadro, sem outros sintomas respiratórios, gastrointestinais ou urinários. Mãe nega sangramentos espontâneos, perda de peso, palidez progressiva ou infecções recorrentes. Ao exame físico, bom estado geral, ativo, boa perfusão periférica. Desconforto ao movimentar os membros inferiores. Na pele, presença de petéquias dispersas, púrpuras, pequenas, não palpáveis e sem equimoses grandes. Ausência de visceromegalias e de linfonodomegalias. Os joelhos e tornozelos estão dolorosos à palpação, sem calor ou edema.\n\nHemograma\nComponente | Resultado | Valor de referência\nLeucócitos | 8.200/mm³ | 5.000 a 15.000/mm³\nHemoglobina | 12,3 g/dL | 11,5 a 13,5 g/dL\nHematócrito | 37 % | 40 a 50 %\nPlaquetas | 18.000/mm³ | 150.000 a 450.000/mm³\n*Contagem diferencial de Leucócitos sem alterações.\n**Provas de coagulação normais.\n\nQual é o diagnóstico provável?",
