    "clinicalCase": "Mulher, 47 anos, G3 PV2 PC1 A0, comparece ao ambulatório de Ginecologia referindo sangramento uterino anormal há 4 anos. Menarca aos 11 anos, coitarca aos 18 anos. Beta HCG sérico realizado há 3 dias, com resultado negativo. Traz ultrassonografia transvaginal com imagem ovalada e pedículo vascularizado em fundo uterino, medindo 0,6 cm. Endométrio com 9 mm de espessura. Realizou histeroscopia para resseção da lesão. Exame histopatológico evidenciou projeção digitiforme de tecido glandular, com pedículo vascular.\nQual é o provável diagnóstico dessa paciente?",
