    "clinicalCase": "Mulher, 82 anos, em acompanhamento pela equipe de Saúde da Família devido à doença coronariana crônica, insuficiência cardíaca com fração de ejeção do ventrículo esquerdo de 53% e doença renal crônica (clearance de creatinina 42 mL/min, VR: 60 a 100 mL/min), em uso de losartana, metoprolol, espironolactona, AAS e rosuvastatina. Durante a consulta médica de acompanhamento, a paciente relata alguns episódios de tontura ao levantar e fadiga nos últimos dias.\nAlém da monitorização da PA, qual estratégia deve ser adotada no plano terapêutico?",
