    "itemCode": "ITEM 169142 - V. 942402",
    "clinicalCase": "Um jovem de 18 anos procura atendimento médico queixando-se de um abaulamento na região inguinal direita que surgiu há cerca de 4 meses. Relata que a tumoração aparece quando ele carrega peso, mas desaparece completamente ao se deitar. Nega dor, vômitos ou distensão abdominal. Ao exame físico, nota-se uma massa redutível que se projeta pelo anel inguinal externo durante a manobra de Valsalva. O examinador realiza a manobra de oclusão do anel inguinal profundo (ponto médio entre a espinha ilíaca anterosuperior e a sínfise púbica) e solicita nova manobra de Valsalva. Durante a compressão firme do anel profundo, o abaulamento não se exterioriza.\nQual a classificação da hérnia nesse caso?",
    "options": [
      {
        "id": "A",
        "text": "Inguinal Direta.",
        "isCorrect": false,
        "explanation": "Incorreta. Na hérnia inguinal direta, o saco herniário se projeta pelo trígono de Hesselbach (medialmente aos vasos epigástricos inferiores); portanto, a oclusão do anel inguinal profundo NÃO impede a sua exteriorização durante a manobra de Valsalva."
      },
      {
        "id": "B",
        "text": "Inguinal Indireta.",
        "isCorrect": true,
        "explanation": "Correta. A manobra descrita é a manobra de Landivar (oclusão digital do anel inguinal interno/profundo). Como a hérnia inguinal indireta tem origem no anel inguinal profundo e percorre o canal inguinal no interior do funículo espermático, a compressão firme do anel profundo impede a descida e exteriorização da massa durante o esforço."
      },
      {
        "id": "C",
        "text": "Femoral.",
        "isCorrect": false,
        "explanation": "Incorreta. A hérnia femoral (ou crural) localiza-se abaixo do ligamento inguinal, no canal femoral, medialmente à veia femoral, não emergindo pelo anel inguinal externo."
      },
      {
        "id": "D",
        "text": "Mista.",
        "isCorrect": false,
        "explanation": "Incorreta. A hérnia mista (em pantalona) contém componentes direto e indireto simultâneos; na manobra de compressão do anel profundo, o componente direto ainda se projetaria."
      }
    ],
    "correctAnswer": "B",
